  'campaign.invite.linkLabel': 'Accessible label for the read-only invite-link field in the InvitePanel (SeamlessInput required label, not visible text). Terse, ~2 words.',
  'campaign.invite.create': 'Button label in the InvitePanel that mints a new invite link when none is active. Brand-voiced, ~3 words.',
  'campaign.invite.copy': 'Button label in the InvitePanel that copies the active invite link to the clipboard. Terse, ~2 words.',
  'campaign.invite.copied': 'Transient confirmation label swapped onto the copy button just after the invite link is copied. Terse, ~1 word.',
  'campaign.invite.share': 'Button label in the InvitePanel that opens the native share sheet for the invite link. Terse, ~1 word.',
  'campaign.invite.replace': 'Button label in the InvitePanel that revokes the current link and mints a fresh one (offered at the invite cap). Terse, ~2 words.',
  'campaign.invite.expand': 'Label on the quiet collapsed invite affordance below a character reveal / setup beat — opening it reveals the full share panel. Terse, ~2-3 words, e.g. "Invite a friend".',
  'campaign.invite.replacePrompt': 'One-beat confirm prompt shown after Replace is pressed, before the link is regenerated — states the consequence (the old link stops working). Calm, ~1 short sentence.',
